20	public final class Util {
21	    private static final ObjectMapper MAPPER = new ObjectMapper();
22	    public static final List<String> CATEGORIES = List.of("Chinese", "Western", "Japanese", "Light Meal", "Korean", "Southeast Asian");
23	    public static final List<String> SPICE = List.of("None", "Mild", "Medium", "Hot");
24	    public static final List<String> ALLERGENS = List.of("Peanuts", "Dairy", "Egg", "Gluten", "Soy", "Fish", "Shellfish");
25	    public static final List<String> MEALS = List.of("Lunch", "Dinner");
26	    public static final List<String> ORDER_STATUSES = List.of("Pending", "Confirmed", "Completed", "Cancelled");
27	
28	    private Util() {}
29	
30	    public static String money(long cents) {
31	        long abs = Math.abs(cents);
32	        return (cents < 0 ? "-" : "") + "¥" + (abs / 100) + "." + String.format("%02d", abs % 100);
