43	    public static <T> T fromJson(String s, Class<T> c) {
44	        try { return MAPPER.readValue(s, c); } catch (Exception e) { throw new IllegalStateException(e); }
45	    }
46	
47	    public static Map<String, Object> parseMap(String json) {
48	        try {
49	            if (json == null || json.isBlank()) return new LinkedHashMap<>();
50	            return MAPPER.readValue(json, new com.fasterxml.jackson.core.type.TypeReference<LinkedHashMap<String, Object>>() {});
51	        } catch (Exception e) { return new LinkedHashMap<>(); }
52	    }
53	
54	    public static List<String> parseList(String json) {
55	        try {
56	            if (json == null || json.isBlank()) return new ArrayList<>();
57	            return MAPPER.readValue(json, new com.fasterxml.jackson.core.type.TypeReference<List<String>>() {});
58	        } catch (Exception e) { return new ArrayList<>(); }
59	    }
