62	        try {
63	            if (json == null || json.isBlank()) return new ArrayList<>();
64	            return MAPPER.readValue(json, new com.fasterxml.jackson.core.type.TypeReference<List<Map<String, Object>>>() {});
65	        } catch (Exception e) { return new ArrayList<>(); }
66	    }
