69	        try {
70	            return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));
71	        } catch (Exception e) { throw new IllegalStateException(e); }
72	    }
