74	    public static long cents(Object o) {
75	        if (o == null) return 0L;
76	        if (o instanceof Number n) return n.longValue();
77	        return Long.parseLong(String.valueOf(o));
78	    }
79	
80	    public static int intVal(Object o) {
81	        if (o == null) return 0;
82	        if (o instanceof Boolean b) return b ? 1 : 0;
83	        if (o instanceof Number n) return n.intValue();
84	        String s = String.valueOf(o);
85	        if ("true".equalsIgnoreCase(s)) return 1;
86	        if ("false".equalsIgnoreCase(s)) return 0;
87	        return Integer.parseInt(s);
88	    }
