143	    public record Effective(LocalDate date, String meal, boolean autoSwitched) {}
144	
145	    public static String canonicalSubmit(Dtos.SubmitReq req) {
146	        List<Map<String, Object>> items = new ArrayList<>();
147	        for (Dtos.ItemReq i : req.items()) {
148	            Map<String, Object> m = new LinkedHashMap<>();
149	            m.put("dishId", i.dishId());
150	            m.put("qty", i.qty());
151	            List<Long> ops = new ArrayList<>(i.optionIds() == null ? List.of() : i.optionIds());
152	            ops.sort(Long::compareTo);
153	            m.put("optionIds", ops);
154	            items.add(m);
155	        }
156	        items.sort((a, b) -> Long.compare((Long) a.get("dishId"), (Long) b.get("dishId")));
157	        Map<String, Object> root = new LinkedHashMap<>();
158	        root.put("items", items);
159	        root.put("deliveryDate", req.deliveryDate());
160	        root.put("mealType", req.mealType());
161	        root.put("address", req.address() == null ? null : req.address().trim());
162	        root.put("confirmAutoSwitch", req.confirmAutoSwitch());
163	        return sha256(json(root));
164	    }
165	
166	    public static String priceDisplay(long cents) { return money(cents); }
167	
168	    /** ISO-8601 timestamp in Asia/Shanghai with offset, e.g. 2026-11-14T22:00:00+08:00. */
169	    public static String iso(Object o) {
170	        if (o == null) return null;
171	        if (o instanceof java.time.LocalDateTime ldt) return ldt.atZone(RequestContext.ZONE).toOffsetDateTime().toString();
172	        if (o instanceof java.sql.Timestamp ts) return ts.toLocalDateTime().atZone(RequestContext.ZONE).toOffsetDateTime().toString();
173	        if (o instanceof java.time.LocalDate ld) return ld.toString();
174	        if (o instanceof java.time.OffsetDateTime odt) return odt.toString();
175	        if (o instanceof java.time.ZonedDateTime zdt) return zdt.toOffsetDateTime().toString();
176	        return String.valueOf(o);
177	    }
178	
179	    public static ZoneId zone() { return RequestContext.ZONE; }
180	}

